public class E310 {
    interface Greet { default String hi(){ return "iface-default"; } }
    abstract static class Abs { abstract String hello(); }
    static class Impl extends Abs implements Greet {
        @Override String hello(){ return "abs-impl"; }
    }
    public static void main(String[] args) {
        Abs a = new Impl();
        Greet g = new Impl();
        System.out.println(a.hello());
        System.out.println(g.hi());
    }
}
